import{_ as e,o as d,c as a,am as l}from"./chunks/framework._FJXuPhs.js";const h=JSON.parse('{"title":"Java深拷贝操作","description":"","frontmatter":{"title":"Java深拷贝操作","excerpt":"摘要","date":"2024-10-24 11:01:53","updated":"2024-10-24 11:01:53"},"headers":[],"relativePath":"基础/核心类库/Java深拷贝操作.md","filePath":"基础/核心类库/Java深拷贝操作.md","lastUpdated":null}'),o={name:"基础/核心类库/Java深拷贝操作.md"};function r(c,t,i,n,s,p){return d(),a("div",null,[...t[0]||(t[0]=[l('<h3 id="基础内容" tabindex="-1">基础内容 <a class="header-anchor" href="#基础内容" aria-label="Permalink to &quot;基础内容&quot;">​</a></h3><p>参考：</p><ul><li><a href="https://www.cnblogs.com/wk-missQ1/p/12809658.html" target="_blank" rel="noreferrer">https://www.cnblogs.com/wk-missQ1/p/12809658.html</a></li></ul><p>深拷贝</p><ul><li>深拷贝会递归地复制原对象及其所有层次的成员对象</li></ul><p>实现方式</p><ul><li>实现<code>Cloneable</code>接口并重写<code>clone()</code>方法</li><li>使用序列化和反序列化</li><li>使用第三方库</li></ul><p>浅拷贝（Shallow Copy）和深拷贝（Deep Copy）的区别：</p><table tabindex="0"><thead><tr><th>特性</th><th>浅拷贝</th><th>深拷贝</th></tr></thead><tbody><tr><td>拷贝范围</td><td>仅拷贝对象的基本类型字段和引用。</td><td>拷贝对象及其所引用的所有对象。</td></tr><tr><td>内部对象是否重用</td><td>浅拷贝后的两个对象共享同一引用对象。</td><td>每个对象包括其内部引用对象都是独立的副本。</td></tr><tr><td>对象的独立性</td><td>对拷贝前后两个对象的操作互相影响。</td><td>拷贝前后两个对象完全独立，互不影响。</td></tr><tr><td>速度与效率</td><td>通常比深拷贝速度快，效率高。</td><td>通常比浅拷贝速度慢，效率低。</td></tr><tr><td>实现难度</td><td>实现简单，直接调用<code>clone()</code>方法即可。</td><td>实现复杂，需要递归或序列化等方法。</td></tr><tr><td>是否涉及递归</td><td>否，只拷贝当前层次的字段。</td><td>是，需要递归拷贝所有层次的对象。</td></tr><tr><td>典型实现方法</td><td>通过<code>Cloneable</code>接口和默认的<code>clone()</code>方法。</td><td>使用<code>Cloneable</code>接口并重写<code>clone()</code>方法，或通过序列化。</td></tr></tbody></table><h3 id="使用工具类没有拷贝-bigdecimal-类型字段排查" tabindex="-1">使用工具类没有拷贝 BigDecimal 类型字段排查 <a class="header-anchor" href="#使用工具类没有拷贝-bigdecimal-类型字段排查" aria-label="Permalink to &quot;使用工具类没有拷贝 BigDecimal 类型字段排查&quot;">​</a></h3><ul><li>大概率可能是因为这个是引用类型，而同等类下有一个字段是 Integer ，可能是Integer 有缓存？？（并不是）</li></ul>',11)])])}const m=e(o,[["render",r]]);export{h as __pageData,m as default};
